import threading

# Sample data representing a list of routed VLAN interfaces and their IPv6 neighbors.
vlan_interfaces = {
    "VLAN1": {
        "interface_id": "VLAN1",
        "ipv6_neighbors": {
            "2001:db8::1": {"mac_address": "00:1a:2b:3c:4d:5e", "state": "REACHABLE"},
            "2001:db8::2": {"mac_address": "00:1a:2b:3c:4d:5f", "state": "STALE"},
        }
    },
    "VLAN2": {
        "interface_id": "VLAN2",
        "ipv6_neighbors": {
            "2001:db8::3": {"mac_address": "00:1a:2b:3c:4d:60", "state": "DELAY"},
        }
    },
}

# Thread-safe locks for handling concurrent access
lock = threading.Lock()

def get_ipv6_neighbor_details(interface_id, neighbor_id=None):
    """
    Retrieves the details of a specific IPv6 neighbor from a list of routed VLAN interfaces.

    Parameters:
    - interface_id (str): The ID of the VLAN interface (e.g., "VLAN1").
    - neighbor_id (str, optional): The IPv6 address of the neighbor (e.g., "2001:db8::1").

    Returns:
    - dict or list: Details of the IPv6 neighbor or a list of neighbors.
    - str: Error message if the interface or neighbor is not found.
    """
    with lock:
        interface = vlan_interfaces.get(interface_id)
        if not interface:
            return f"No interface found with ID: {interface_id}"

        ipv6_neighbors = interface.get('ipv6_neighbors')
        if ipv6_neighbors:
            if neighbor_id:
                neighbor_details = ipv6_neighbors.get(neighbor_id)
                if not neighbor_details:
                    return f"No IPv6 neighbor found with address {neighbor_id} on interface {interface_id}"
                return neighbor_details
            else:
                return [{neighbor: details} for neighbor, details in ipv6_neighbors.items()]
        else:
            return f"No IPv6 neighbors found for interface {interface_id}"

# Example usage of the function
if __name__ == "__main__":
    neighbor_details = get_ipv6_neighbor_details("VLAN1", "2001:db8::1")
    print(neighbor_details)  # Should print details of the neighbor with address 2001:db8::1 on VLAN1
    all_neighbors = get_ipv6_neighbor_details("VLAN1")
    print(all_neighbors)  # Should print details of all neighbors on VLAN1
