import threading

class CapacityValue:
    def __init__(self, value):
        self.value = value

class NetworkNode:
    def __init__(self, node_id, peak_burst_size):
        self.node_id = node_id
        self.peak_burst_size = CapacityValue(peak_burst_size)

class ContextTopology:
    def __init__(self, context_id):
        self.context_id = context_id
        self.nodes = {}

    def add_node(self, node):
        self.nodes[node.node_id] = node

class NetworkTopology:
    def __init__(self):
        self.contexts = {}
        self.lock = threading.Lock()

    def add_context(self, context):
        with self.lock:
            self.contexts[context.context_id] = context

    def get_peak_burst_size(self, context_id, node_id):
        """
        Retrieves the peak burst size of a network node within a specified context topology.

        Parameters:
        context_id (int): Unique identifier for the context topology.
        node_id (int): Unique identifier for the network node within the context topology.

        Returns:
        CapacityValue or None: The peak burst size as a CapacityValue object, or None if the context_id or node_id does not exist.
        """
        with self.lock:
            context = self.contexts.get(context_id)
            if not context:
                return None
            node = context.nodes.get(node_id)
            if not node:
                return None
            return node.peak_burst_size

# Example usage
network_topology = NetworkTopology()
context = ContextTopology(1)
context.add_node(NetworkNode(101, 123456))
context.add_node(NetworkNode(102, 654321))
network_topology.add_context(context)

# Now we can call get_peak_burst_size in a concurrent environment
print(network_topology.get_peak_burst_size(1, 101).value)  # Output: 123456
print(network_topology.get_peak_burst_size(1, 102).value)  # Output: 654321
print(network_topology.get_peak_burst_size(2, 103))        # Output: None
