def convert_to_config_format(value):
    """
    Recursively converts each value in a nested dictionary to a string according to specific rules:
    - Strings remain unchanged.
    - Booleans are converted to 'true' or 'false'.
    - None values are converted to an empty string.
    - All other data types are converted to their string representation.

    :param value: The input value which can be a nested dictionary or any data type.
    :return: A nested dictionary with all values converted to strings.
    """
    if isinstance(value, dict):
        return {k: convert_to_config_format(v) for k, v in value.items()}
    elif isinstance(value, bool):
        return 'true' if value else 'false'
    elif value is None:
        return ''
    else:
        return str(value)

# Example usage:
config_data = {
    'name': 'ApplicationName',
    'version': 1.0,
    'debug_mode': True,
    'release_mode': False,
    'api_key': None,
    'features': {
        'feature1': True,
        'feature2': False,
        'feature3': None,
        'feature4': 42,
        'feature5': {
            'nested_feature': 'value',
            'nested_feature2': False
        }
    }
}

converted_config_data = convert_to_config_format(config_data)
print(converted_config_data)
