from concurrent.futures import ThreadPoolExecutor

def map_dscp_to_cos(dscp_values):
    """
    Maps a list of DSCP values to their corresponding CoS values concurrently.

    Parameters:
    dscp_values (list of int): A list of DSCP values to be mapped.

    Returns:
    dict: A dictionary mapping valid DSCP values to their corresponding CoS values.
    """
    def dscp_to_cos(dscp):
        if 0 <= dscp <= 31:
            return 0
        elif 32 <= dscp <= 47:
            return 1
        elif 48 <= dscp <= 55:
            return 2
        elif 56 <= dscp <= 63:
            return 3
        else:
            return None

    cos_dict = {}

    with ThreadPoolExecutor() as executor:
        future_to_dscp = {executor.submit(dscp_to_cos, dscp): dscp for dscp in dscp_values}
        for future in future_to_dscp:
            cos_value = future.result()
            dscp = future_to_dscp[future]
            if cos_value is not None:
                cos_dict[dscp] = cos_value

    return cos_dict

# Example usage:
dscp_values = [0, 10, 40, 50, 60, 70]
cos_map = map_dscp_to_cos(dscp_values)
print(cos_map)
```

