def get_new_shape(name: str, shape: tuple, num_heads: int) -> tuple:
    """
    Determines the new shape of a weight matrix or bias vector for a multi-head self-attention mechanism.

    :param name: The name of the weight matrix or bias vector.
    :param shape: The original shape of the weight matrix or bias vector.
    :param num_heads: The number of attention heads.
    :return: The new shape of the weight matrix or bias vector after reshaping, or None if the name does not match any pattern.
    :raises ValueError: If the shape is not divisible as expected.
    """
    if "self_attention/attention_output/kernel" in name:
        if shape[0] % num_heads != 0:
            raise ValueError(f"The first dimension of the shape {shape} is not divisible by the number of heads {num_heads}")
        return (num_heads, shape[0] // num_heads, shape[1])

    elif "self_attention/attention_output/bias" in name:
        return shape

    elif ("self_attention/query" in name or "self_attention/value" in name or "self_attention/key" in name):
        if "kernel" in name:
            if shape[1] % num_heads != 0:
                raise ValueError(f"The second dimension of the shape {shape} is not divisible by the number of heads {num_heads}")
            return (shape[0], num_heads, shape[1] // num_heads)
        elif "bias" in name:
            if shape[0] % num_heads != 0:
                raise ValueError(f"The first dimension of the shape {shape} is not divisible by the number of heads {num_heads}")
            return (num_heads, shape[0] // num_heads)

    return None
