def format_full_name(full_name):
    """
    Formats a full name by removing leading/trailing whitespace, capitalizing each word,
    and preserving hyphenated or apostrophe-containing words as-is except for capitalization.

    :param full_name: A string representing the full name.
    :return: A formatted string with the full name.
    """
    def capitalize_word(word):
        if '-' in word or "'" in word:
            parts = word.split('-') if '-' in word else word.split("'")
            parts = [part.capitalize() for part in parts]
            return '-'.join(parts) if '-' in word else "'".join(parts)
        else:
            return word.capitalize()

    full_name = full_name.strip()
    words = full_name.split()
    formatted_words = [capitalize_word(word) for word in words]
    return ' '.join(formatted_words)
