import json

def convert_to_json(data):
    """
    Converts a nested data structure into a JSON string.

    Args:
    data (dict, list, str, int, float): The data structure to convert.

    Returns:
    str: A JSON string representation of the input data structure.

    Raises:
    ValueError: If the data contains non-serializable types or circular references.
    """
    try:
        return json.dumps(data, check_circular=True)
    except TypeError:
        raise ValueError("Data contains non-serializable types.")
    except RecursionError:
        raise ValueError("Circular reference detected.")

# Example usage:
