from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/calculate', methods=['GET'])
def calculate():
    """
    Perform arithmetic operations based on query parameters.

    Returns:
        jsonify: A JSON response containing the result of the operation or an error message.
    """
    # Extract parameters from query
    num1 = request.args.get('num1', type=float)
    num2 = request.args.get('num2', type=float)
    operation = request.args.get('operation', type=str)

    # Validate the input
    if num1 is None or num2 is None or operation is None:
        return jsonify({"error": "Invalid parameters. Please ensure to provide num1, num2, and operation."}), 400

    # Perform the specified operation
    if operation == 'add':
        result = num1 + num2
    elif operation == 'subtract':
        result = num1 - num2
    elif operation == 'multiply':
        result = num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            return jsonify({"error": "Cannot divide by 0"}), 400
        result = num1 / num2
    else:
        return jsonify({"error": "Invalid operation. Please use 'add', 'subtract', 'multiply', or 'divide'."}), 400

    # Return the result
    return jsonify({"result": result})

if __name__ == '__main__':
    app.run(debug=True)
