class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new key into the BST."""
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, root, key):
        if root.val < key:
            if root.right is None:
                root.right = Node(key)
            else:
                self._insert(root.right, key)
        else:
            if root.left is None:
                root.left = Node(key)
            else:
                self._insert(root.left, key)

    def delete(self, key):
        """Delete a key from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, root, key):
        if root is None:
            return root

        if key < root.val:
            root.left = self._delete(root.left, key)

        elif key > root.val:
            root.right = self._delete(root.right, key)

        else:
            if root.left is None:
                return root.right

            elif root.right is None:
                return root.left

            root.val = self.min_value_node(root.right).val
            root.right = self._delete(root.right, root.val)

        return root

    def search(self, key):
        """Search for a key in the BST."""
        return self._search(self.root, key)

    def _search(self, root, key):
        if root is None or root.val == key:
            return root

        if root.val < key:
            return self._search(root.right, key)

        return self._search(root.left, key)

    def min_value_node(self, node):
        """Find the node with the minimum value in the BST."""
        current = node
        while current.left is not None:
            current = current.left

        return current

    def max_value_node(self, node):
        """Find the node with the maximum value in the BST."""
        current = node
        while current.right is not None:
            current = current.right

        return current

    def get_min(self):
        """Return the minimum value in the BST."""
        if self.root is not None:
            return self.min_value_node(self.root).val
        else:
            return None

    def get_max(self):
        """Return the maximum value in the BST."""
        if self.root is not None:
            return self.max_value_node(self.root).val
        else:
            return None


# Example usage of the BST class
bst = BST()
elements_to_insert = [20, 8, 22, 4, 12, 10, 14]

for element in elements_to_insert:
    bst.insert(element)

value_to_search = 10
search_result = bst.search(value_to_search)
print('Found' if search_result else 'Not Found')

value_to_delete = 12
bst.delete(value_to_delete)

search_result_after_deletion = bst.search(value_to_delete)
print('Found' if search_result_after_deletion else 'Not Found')
```

