class BookstoreInventory:
    def __init__(self):
        """Initialize the bookstore inventory with empty lists for titles and prices."""
        self.book_titles = []
        self.book_prices = []

    def add_book(self, title, price):
        """Add a new book with the given title and price."""
        self.book_titles.append(title)
        self.book_prices.append(price)

    def remove_book(self, title):
        """Remove a book by title. Handle the exception if the book is not found."""
        try:
            index = self.book_titles.index(title)
            self.book_titles.pop(index)
            self.book_prices.pop(index)
        except ValueError:
            print(f"Error: Book '{title}' not found in inventory.")

    def list_books(self):
        """List all books with their prices."""
        if not self.book_titles:
            print("No books in inventory.")
        else:
            for title, price in zip(self.book_titles, self.book_prices):
                print(f"- {title}: ${price:.2f}")

    def average_price(self):
        """Calculate and return the average price of all books in inventory."""
        if not self.book_prices:
            return 0
        return sum(self.book_prices) / len(self.book_prices)
